import tokens


def evaluate(text):
    toks = tokens.tokenize(text)
    total = 0
    sign = 1
    for kind, value, _pos in toks:
        if kind == "NUM":
            total += sign * int(value)
        elif value == "-":
            sign = -1
        else:
            sign = 1
    return str(total)

